    S.append(sol(K3, 'ចម្លើយ ខ.', p('រកគ្រប់ចំនួនគត់គូ ' + m('n') + ' ដែល ' + m('72 < n \\le 90') + ' ៖') + p('ចំនួនគត់គូ គឺជាចំនួនគត់ដែលចែកដាច់នឹង ' + m('2') + ' (មានលេខខ្ទង់រាយជា ' + m('0, 2, 4, 6, 8') + ') ។') + p('ដោយ ' + m('72 < n \\le 90') + ' នោះ ' + m('n') + ' ត្រូវតែជាចំនួនគត់គូដែលធំជាង ' + m('72') + ' និងតូចជាង ឬស្មើ ' + m('90') + ' (រាប់បញ្ចូលទាំង ' + m('90') + ') ។') + fig(numline(71, 91, pts={i: BLUE for i in range(74, 91, 2)}, w=1100)) + p('ដូចនេះ ៖ ' + hl(m('n \\in \\{74, 76, 78, 80, 82, 84, 86, 88, 90\\}'), BLUE))))
